'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const sdk = require('../../pisdk');
(async () => {
  const cwd = path.join(process.env.HOME, 'workspace'); await fs.mkdir(cwd, { recursive: true });
  await fs.writeFile(path.join(cwd, 'space name.txt'), 'fixture');
  const base = { cwd, env: process.env, extraArgs: ['-e', path.join(__dirname, 'pisdk-probe.ts'), '-e', path.join(__dirname, 'pi-composer-extension.ts')] };
  const warm = await sdk.piBeginWarm(base), target = { ...base, sessionPath: warm.file };
  const initial = await fs.readFile(warm.file, 'utf8');
  const list = await sdk.piComposer(target, { action: 'commands' });
  assert.ok(list.commands.some(c => c.name === 'composer-choice' && c.source === 'extension'));
  const query = async (text, force = false) => {
    const input = { action: 'complete', clientId: 'tab1', text, cursor: text.length, force };
    return { input, result: await sdk.piComposer(target, input) };
  };
  const args = await query('/composer-choice red');
  assert.equal(args.result.items[0].value, 'redblue');
  const inserted = await sdk.piComposer(target, { ...args.input, action: 'apply', snapshot: args.result.snapshot, itemIndex: 0 });
  assert.equal(inserted.text, '/composer-choice redblue');
  const extension = await query('#cell');
  assert.equal(extension.result.items[0].description, '#cell', 'extension reads HTML draft, not an empty editor');
  const custom = await sdk.piComposer(target, { ...extension.input, action: 'apply', snapshot: extension.result.snapshot, itemIndex: 0 });
  assert.deepEqual(custom, { text: 'cell:7', cursor: 5 });
  const file = await query('./space', true);
  const i = file.result.items.findIndex(item => item.label === 'space name.txt');
  assert.ok(i >= 0, 'native provider completes files');
  const fileEdit = await sdk.piComposer(target, { ...file.input, action: 'apply', snapshot: file.result.snapshot, itemIndex: i });
  assert.match(fileEdit.text, /".*space name\.txt"/);
  assert.equal(await fs.readFile(warm.file, 'utf8'), initial, 'completion does not append messages');
  const old = await query('#old');
  await sdk.piHeadlessRun(target, { message: '/reload' }).done;
  await assert.rejects(sdk.piComposer(target, { ...old.input, action: 'apply', snapshot: old.result.snapshot, itemIndex: 0 }), /expired/);
  assert.equal((await query('#new')).result.items[0].description, '#new', 'wrappers rebound after reload');
  const model = await query('/model fixture/');
  assert.ok(model.result.items.some(i => i.value === 'fixture/one'));
  await assert.rejects(sdk.piHeadlessRun(target, { message: '/settings' }).done, /HTML settings control/);
  const notices = [];
  await sdk.piHeadlessRun(target, { message: '/composer-choice blue', onEvent: e => { if (e.method === 'notify') notices.push(e.message); } }).done;
  assert.ok(notices.includes('chosen:blue'));
  assert.equal(sdk.listWarmSessions().length, 1); assert.equal(sdk.listWarmSessions()[0].pid, warm.pid);
  await assert.rejects(fs.access(process.env.FIXTURE_REQUEST_MARKER), /ENOENT/);
  console.log(JSON.stringify({ commands: true, arguments: true, files: true, extensions: true, reload: true, modelCalls: 0 }));
})().catch(e => { console.error(e.stack); process.exitCode = 1; }).finally(() => sdk.stopAllWarmSessions());
